// Тема: «Разработка прототипа сервиса по выбору научного руководителя
//        для выпускных квалификационных работ в высшем учебном заведении»
// Оформление: точное соответствие шаблону Давлетьярова И.М.
// =============================================================================

const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle,
  WidthType, ShadingType, VerticalAlign, PageBreak,
  TabStopType, TableOfContents, StyleLevel, PageNumber, Header, Footer,
  convertInchesToTwip,
} = require('docx');
const fs = require('fs');

// ----- Базовые константы оформления ----------------------------------------
const FONT = 'Times New Roman';
const FONT_SIZE = 28;        // 14 pt (half-points)
const FONT_SIZE_SMALL = 24;  // 12 pt
const MARGIN_LEFT = 1800;
const MARGIN_RIGHT = 1008;
const MARGIN_TOP = 1134;
const MARGIN_BOTTOM = 1134;
const COLOR_BLACK = '000000';

// ----- Низкоуровневые помощники --------------------------------------------
function makeText(text, opts = {}) {
  return new TextRun({
    text: String(text),
    font: opts.font || FONT,
    size: opts.size || FONT_SIZE,
    bold: opts.bold || false,
    italics: opts.italics || false,
    color: opts.color || COLOR_BLACK,
    underline: opts.underline ? {} : undefined,
  });
}

function para(text, opts = {}) {
  const runs = (typeof text === 'string')
    ? [makeText(text, opts.runOpts || {})]
    : text;
  return new Paragraph({
    children: runs,
    alignment: opts.align || AlignmentType.JUSTIFIED,
    spacing: {
      before: opts.before || 0,
      after: opts.after || 0,
      line: 276,
      lineRule: 'auto',
    },
    indent: opts.indent === false ? undefined : { firstLine: 709 },
    pageBreakBefore: opts.pageBreak || false,
  });
}

function centerPara(text, opts = {}) {
  return para(text, { ...opts, align: AlignmentType.CENTER, indent: false });
}

function rightPara(text, opts = {}) {
  return para(text, { ...opts, align: AlignmentType.RIGHT, indent: false });
}

function emptyLine() {
  return new Paragraph({
    children: [makeText('')],
    spacing: { before: 0, after: 0, line: 276, lineRule: 'auto' },
  });
}

// Заголовок 1-го уровня (главы) — крупно, по центру, ЧЁРНЫЙ, новая страница
function heading1(text, pageBreak = true) {
  return new Paragraph({
    children: [makeText(text, { bold: true, size: FONT_SIZE, color: COLOR_BLACK })],
    heading: HeadingLevel.HEADING_1,
    alignment: AlignmentType.CENTER,
    spacing: { before: 240, after: 240, line: 276, lineRule: 'auto' },
    pageBreakBefore: pageBreak,
  });
}

// Заголовок 2-го уровня (разделы) — слева, ЧЁРНЫЙ, ВСЕГДА новая страница
function heading2(text) {
  return new Paragraph({
    children: [makeText(text, { bold: true, size: FONT_SIZE, color: COLOR_BLACK })],
    heading: HeadingLevel.HEADING_2,
    alignment: AlignmentType.LEFT,
    spacing: { before: 240, after: 200, line: 276, lineRule: 'auto' },
    indent: { firstLine: 709 },
    pageBreakBefore: true,
  });
}

// Заголовок 3-го уровня (подразделы) — без разрыва страницы
function heading3(text) {
  return new Paragraph({
    children: [makeText(text, { bold: true, size: FONT_SIZE, color: COLOR_BLACK })],
    heading: HeadingLevel.HEADING_3,
    alignment: AlignmentType.LEFT,
    spacing: { before: 200, after: 120, line: 276, lineRule: 'auto' },
    indent: { firstLine: 709 },
  });
}

// Маркированный список — настоящий list-параграф (без префиксов "- ")
function bullet(text, level = 0) {
  const runs = (typeof text === 'string')
    ? [makeText(text)]
    : text;
  return new Paragraph({
    children: runs,
    alignment: AlignmentType.JUSTIFIED,
    spacing: { before: 0, after: 0, line: 276, lineRule: 'auto' },
    numbering: { reference: 'bullet-list', level },
  });
}

// Нумерованный список
function numItem(text, level = 0) {
  const runs = (typeof text === 'string')
    ? [makeText(text)]
    : text;
  return new Paragraph({
    children: runs,
    alignment: AlignmentType.JUSTIFIED,
    spacing: { before: 0, after: 0, line: 276, lineRule: 'auto' },
    numbering: { reference: 'num-list', level },
  });
}

function figureCaption(text) {
  return new Paragraph({
    children: [makeText(text, { size: FONT_SIZE })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 120, after: 240, line: 276, lineRule: 'auto' },
  });
}

function tableCaption(text) {
  return new Paragraph({
    children: [makeText(text, { size: FONT_SIZE })],
    alignment: AlignmentType.LEFT,
    spacing: { before: 240, after: 120, line: 276, lineRule: 'auto' },
    indent: { firstLine: 0 },
  });
}

function placeholder(text) {
  return new Paragraph({
    children: [makeText(`[[${text}]]`, { italics: true, color: '808080' })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 240, after: 240, line: 276, lineRule: 'auto' },
  });
}

// ----- Таблицы --------------------------------------------------------------
const cellBorder = { style: BorderStyle.SINGLE, size: 4, color: '000000' };
const allBorders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };

function tCell(text, opts = {}) {
  const content = Array.isArray(text)
    ? text.map((line) =>
      new Paragraph({
        children: [makeText(line, { bold: opts.bold || false, size: opts.size || FONT_SIZE_SMALL })],
        alignment: opts.align || AlignmentType.LEFT,
        spacing: { before: 40, after: 40, line: 240, lineRule: 'auto' },
        indent: { firstLine: 0 },
      }))
    : [new Paragraph({
      children: [makeText(text, { bold: opts.bold || false, size: opts.size || FONT_SIZE_SMALL })],
      alignment: opts.align || AlignmentType.LEFT,
      spacing: { before: 40, after: 40, line: 240, lineRule: 'auto' },
      indent: { firstLine: 0 },
    })];
  return new TableCell({
    children: content,
    verticalAlign: VerticalAlign.CENTER,
    margins: { top: 80, bottom: 80, left: 100, right: 100 },
    borders: allBorders,
    shading: opts.header ? { fill: 'D9D9D9', type: ShadingType.CLEAR } : undefined,
    width: opts.width ? { size: opts.width, type: WidthType.DXA } : undefined,
  });
}

function makeTable(rows, opts = {}) {
  return new Table({
    rows,
    width: { size: 9000, type: WidthType.DXA },
    borders: {
      top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder,
      insideHorizontal: cellBorder, insideVertical: cellBorder,
    },
    columnWidths: opts.widths,
  });
}

