  r.push(para('Одним из таких процессов является выбор научного руководителя и темы выпускной квалификационной работы (ВКР). От качества организации этого процесса зависят своевременность закрепления тем за обучающимися, прозрачность распределения нагрузки между преподавателями и минимизация организационных конфликтов. В отсутствие специализированной системы взаимодействие между студентом, научным руководителем и заведующим кафедрой осуществляется через личные встречи, электронную почту и бумажные заявления, что приводит к разрозненности данных и отсутствию единой точки контроля статуса заявки.'));

  r.push(para('Актуальность темы исследования определяется необходимостью устранения перечисленных недостатков за счёт перевода процесса организации ВКР в электронную форму. Автоматизация позволяет сократить время согласования заявок, исключить необходимость многократного оформления бумажных заявлений, обеспечить отслеживание статуса заявки в реальном времени и предоставить участникам процесса централизованный канал коммуникации [1].'));

  r.push(para('Особую сложность представляет согласование заявок, в котором задействованы несколько ролей с различными правами доступа: студент, научный руководитель и заведующий кафедрой. Каждая роль имеет свой интерфейс и собственный набор разрешённых действий, а заявка проходит детерминированный жизненный цикл с переходами между статусами, заданными бизнес-правилами вуза. Реализация такой ролевой модели в одном программно-информационном решении требует строгой архитектуры, обеспечивающей разделение ответственности слоёв и тестируемость бизнес-логики.'));

