// =============================================================================
// БЛОК 9. ЗАКЛЮЧЕНИЕ
// =============================================================================
function buildConclusion() {
  const r = [];
  r.push(heading1('ЗАКЛЮЧЕНИЕ'));
  r.push(para('В рамках выпускной квалификационной работы спроектирована и реализована программно-информационная система AcademicTopicSelectionService — прототип веб-сервиса, автоматизирующего процесс выбора научного руководителя и темы выпускной квалификационной работы в высшем учебном заведении.'));
  r.push(para('Решены все поставленные задачи. Проведён анализ предметной области, выделены ключевые сущности (преподаватель, студент, тема ВКР, заявка студента, архив защищённых работ) и охарактеризованы участники процесса с присущими им функциями. Выполнен сравнительный анализ существующих решений — систем управления обучением, универсальных платформ автоматизации бизнес-процессов и специализированных модулей учёта ВКР; показано, что ни одно из рассмотренных решений не обеспечивает в готовом виде полного набора возможностей, необходимых для централизованного управления процессом выбора научного руководителя и темы ВКР.'));
  r.push(para('Сформулированы функциональные и нефункциональные требования к разрабатываемой системе. Выбран и обоснован технологический стек: ASP.NET Core 10 и C# 13 для серверной части, Angular 20 с библиотекой компонентов PrimeNG 20 для клиентской части, СУБД PostgreSQL 16.8, ORM Entity Framework Core 10, кэш-сервер Redis 7, объектное хранилище MinIO / AWS S3, библиотека MailKit для отправки электронной почты и средства контейнеризации Docker и Docker Compose.'));
  r.push(para('Спроектирована и реализована архитектура программной системы по принципам Clean Architecture с разделением серверной части на четыре проекта (Domain, Application, Infrastructure, API). Разработана реляционная модель данных, обеспечивающая целостность связей между пользователями, темами, заявками, сообщениями чата и архивом ВКР; источником истины для схемы базы данных служат SQL-скрипты инициализации.'));
  r.push(para('Реализованы алгоритмы согласования заявок, включающие два связанных жизненных цикла: запроса на научное руководство и заявки на тему ВКР. Атомарность ключевого бизнес-правила автоматической отмены остальных запросов студента при одобрении одного из них обеспечена использованием транзакций базы данных. Реализована подсистема обмена сообщениями между студентом и научным руководителем в рамках заявки с проверкой доступа на уровне сервиса и закрытием чата после терминальных статусов заявки.'));
  r.push(para('Реализована подсистема архивирования защищённых работ с использованием объектного хранилища, совместимого с протоколом Amazon S3, и presigned URL для безопасного скачивания файлов напрямую из хранилища. Реализована подсистема уведомлений с одновременным сохранением уведомления в основной базе данных и постановкой задачи отправки электронной почты в канал асинхронной обработки. Реализован модуль аналитики и экспорта данных для администратора и заведующего кафедрой с поддержкой форматов Excel и CSV.'));
  r.push(para('Реализована подсистема аутентификации и авторизации на основе JWT-токенов доступа и refresh-токенов с ротацией, хранимых в Redis. Доступ к ресурсам ограничен ролевой моделью с проверкой как на уровне политики авторизации эндпоинта, так и на уровне видимости ресурса в прикладном сервисе. Для эндпоинтов аутентификации применено ограничение скорости запросов.'));
  r.push(para('Продемонстрированы примеры использования разработанной программной системы в разрезе четырёх ролей пользователей: студент, преподаватель, заведующий кафедрой и администратор. Для каждой роли описаны типовые сценарии и приведены соответствующие экранные формы клиентской части. Реализованные сценарии подтверждают соответствие разработанной системы заявленным функциональным требованиям.'));
  r.push(para('Перспективы дальнейшего развития работы включают реализацию двухфакторной аутентификации, интеграцию с действующими информационными системами вуза (учётные записи студентов и преподавателей, расписание занятий, нагрузка кафедр), расширение подсистемы уведомлений за счёт мессенджеров (Telegram, корпоративные мессенджеры), внедрение полнотекстового поиска по темам и архивным работам, а также добавление поддержки обмена файлами в чате заявки.'));
  return r;
}

