// БЛОК 12. СБОРКА ДОКУМЕНТА
// =============================================================================
function buildDocument() {
  const children = [];
  children.push(...buildTitlePages());
  children.push(...buildAbstractAndTOC());
  children.push(...buildIntroduction());
  children.push(...buildChapter1());
  children.push(...buildChapter2());
  children.push(...buildChapter3());
  children.push(...buildChapter3Part2());
  children.push(...buildChapter4());
  children.push(...buildConclusion());
  children.push(...buildReferences());
  children.push(...buildAppendices());

  const doc = new Document({
    creator: 'Ильин А.А.',
    title: 'ВКР: Разработка прототипа сервиса по выбору научного руководителя для ВКР',
    description: 'Пояснительная записка к выпускной квалификационной работе',
    styles: {
      paragraphStyles: [
        {
          id: 'Heading1', name: 'Heading 1', basedOn: 'Normal', next: 'Normal', quickFormat: true,
          run: { font: FONT, size: FONT_SIZE, bold: true, color: COLOR_BLACK },
          paragraph: { spacing: { before: 240, after: 240, line: 276, lineRule: 'auto' }, alignment: AlignmentType.CENTER },
        },
        {
          id: 'Heading2', name: 'Heading 2', basedOn: 'Normal', next: 'Normal', quickFormat: true,
          run: { font: FONT, size: FONT_SIZE, bold: true, color: COLOR_BLACK },
          paragraph: { spacing: { before: 240, after: 200, line: 276, lineRule: 'auto' }, alignment: AlignmentType.LEFT, indent: { firstLine: 709 } },
        },
        {
          id: 'Heading3', name: 'Heading 3', basedOn: 'Normal', next: 'Normal', quickFormat: true,
          run: { font: FONT, size: FONT_SIZE, bold: true, color: COLOR_BLACK },
          paragraph: { spacing: { before: 200, after: 120, line: 276, lineRule: 'auto' }, alignment: AlignmentType.LEFT, indent: { firstLine: 709 } },
        },
      ],
      default: {
        document: { run: { font: FONT, size: FONT_SIZE, color: COLOR_BLACK } },
      },
    },
    numbering: {
      config: [
        {
          reference: 'bullet-list',
          levels: [
            {
              level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT,
              style: { paragraph: { indent: { left: 720, hanging: 360 } } },
            },
          ],
        },
        {
          reference: 'num-list',
          levels: [
            {
              level: 0, format: LevelFormat.DECIMAL, text: '%1)', alignment: AlignmentType.LEFT,
              style: { paragraph: { indent: { left: 720, hanging: 360 } } },
            },
          ],
        },
      ],
    },
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: MARGIN_TOP, right: MARGIN_RIGHT, bottom: MARGIN_BOTTOM, left: MARGIN_LEFT,
            },
          },
        },
        footers: {
          default: new Footer({
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [
                  new TextRun({ children: [PageNumber.CURRENT], font: FONT, size: FONT_SIZE_SMALL }),
                ],
              }),
            ],
          }),
        },
        children,
      },
    ],
  });

  return doc;
}

// =============================================================================
// БЛОК 13. ТОЧКА ВХОДА
// =============================================================================
(async () => {
  const doc = buildDocument();
  const buffer = await Packer.toBuffer(doc);
  const outPath = 'dist/Ilyin_VKR_1.docx';
  fs.mkdirSync('dist', { recursive: true });
  fs.writeFileSync(outPath, buffer);
  console.log(`Документ сохранён: ${outPath}`);
})();
